"""Render the saved Round2 numerical and independent source evidence as HTML."""
import html
import json
from pathlib import Path

HERE=Path(__file__).resolve().parent
OUTPUT=HERE/'results/round2/6489ccaec521'


def main():
    r=json.loads((OUTPUT/'round2.json').read_bytes());p=json.loads((HERE/'frozen-division-comparison-v2.json').read_bytes())
    case=r['currentCases'];experiments=r['experiments'];summary=[]
    for variant,contexts in experiments.items():
        for context,c in contexts.items():
            m=c['evaluationPooled']['FBS-FCS'];same=c['evaluationPooled']['FBS-FBS']
            values=(variant,context,m['divisionResidual']['games'],f"{m['refitControl']['predictedWinRate']:.1%}",f"{m['divisionResidual']['predictedWinRate']:.1%}",f"{m['divisionResidual']['observedWinRate']:.1%}",f"{m['refitControl']['logLoss']:.5f}",f"{m['divisionResidual']['logLoss']:.5f}",f"{same['divisionResidual']['logLoss']-same['refitControl']['logLoss']:+.6f}")
            summary.append('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in values)+'</tr>')
    rankings=''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in (t['candidateSorRank'],t['team'],t['record'],t['colleyRank'],t['frozenSorRank'],t['controlSorRank'],t['candidateSorRank']))+'</tr>' for t in case['rows'] if t['candidateSorRank']<=25)
    details=[]
    for team in sorted(case['selectedTeams'],key=lambda t:t['candidateSorRank']):
        games=''.join('<tr>'+''.join('<td>'+html.escape(str(v))+'</td>' for v in (g['opponent'],g['division'].upper(),g['result'],g['venue'],f"{g['controlReferenceWinProbability']:.1%}",f"{g['candidateWithoutDivisionProbability']:.1%}",f"{g['candidateReferenceWinProbability']:.1%}"))+'</tr>' for g in team['games'])
        details.append(f"<details><summary>{html.escape(team['team'])}: control #{team['controlSorRank']} → candidate #{team['candidateSorRank']} ({team['record']})</summary><p>Live Colley #{team['colleyRank']}; frozen original SOR #{team['frozenSorRank']}. Candidate with its slope/home coefficients held fixed but division term set to zero: #{team['candidateWithoutDivisionRank']}. Removing the division term is a diagnostic, not another selected model.</p><div class='scroll'><table><thead><tr><th>Opponent</th><th>Subdivision</th><th>Result</th><th>Venue</th><th>Control average-FBS win chance</th><th>Candidate without gap</th><th>Candidate average-FBS win chance</th></tr></thead><tbody>{games}</tbody></table></div></details>")
    calendar_path=HERE/'results/round2/calendar-sensitivity.json'
    calendar_note='<p>The remaining provider calendar disagreements are disclosed in the source audit.</p>'
    if calendar_path.exists():calendar_note='<p>A separate <a href="../calendar-sensitivity.json">calendar-choice sensitivity check</a> substituted the 29 disputed FCS calendar/time records in memory. None of the 9,803 FBS-involving preweek features changed, and the fitted models and probability scores were exactly unchanged. This diagnoses sensitivity without adjudicating the conflicting facts or changing the frozen model.</p>'
    doc=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FBS Intelligence — Round 2</title>
<style>body{{font:16px/1.65 system-ui,sans-serif;color:#193148;max-width:1240px;margin:32px auto;padding:0 22px}}h1,h2{{line-height:1.25}}.note{{background:#edf4f8;padding:18px;border-left:4px solid #24748c}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{padding:9px;text-align:left;border-bottom:1px solid #d7e1e9}}.scroll{{overflow:auto}}details{{border:1px solid #d7e1e9;margin:12px 0;padding:12px}}summary{{font-weight:650;cursor:pointer}}code{{overflow-wrap:anywhere}}a{{color:#146780}}</style>
<h1>Round 2: repaired evidence, repeated tests, frozen future comparison</h1><p class="note"><strong>The division-aware SOR remains a research candidate.</strong> The public Colley ranking formula, current rankings, displayed SOS and frontend are unchanged. The existing Sunday 8 AM Mountain job now has an additional shadow comparison and before-kickoff prediction capture. This adds no CFBD requests or paid services.</p>
<h2>What the data audit changed</h2><p>We added 34 missing games between known FCS opponents and corrected three 2022 scores using NCAA and school sources. Those score corrections preserve the winners. Earlier FCS playoff rounds were often already present under a provider “regular” label; a zero labeled-postseason count did not mean zero playoff games. We checked actual identities and results.</p>
<p>The repaired data matches all <strong>253 NCAA tournament games</strong> in 2014–2019 and 2021–2025. With SWAC championships and Celebration Bowls checked separately, all 274 expected games in those categories outside pandemic season 2020 match. This does not certify every regular-season FCS or lower-division schedule. The 2020 spring season remains incomplete and outside training and pooled evaluation.</p>
<p><a href="https://s3.amazonaws.com/fs.ncaa.org/Docs/stats/football_records/FCSchamps.pdf">NCAA championship records</a> contain some date and score errors; the <a href="../primary-fcs-checks.json.gz">independent primary-source audit</a> documents school corroboration and exact matches. The three saved-score corrections are in <a href="../../fcs-score-adjudications.json">the adjudication record</a>. Raw source files stay in the local cache; the compact repair release and hashes permit offline restoration.</p>
<h2>Did the original finding survive?</h2><p><strong>Yes.</strong> Using 2014–2019 to fit, the prior-week candidate estimates FBS success at 93.6% across 602 FBS–FCS games in 2021–2025; the nested division-blind control estimates 65.7%, and the observed rate is 94.4%. Crossdivision probability scores improve in all five evaluation seasons and all three network checks. Historical years have already been inspected; they are not untouched tests.</p>
<div class="scroll"><table><thead><tr><th>Network</th><th>Context</th><th>Games</th><th>Control expected FBS wins</th><th>Candidate expected</th><th>Actual</th><th>Control log loss</th><th>Candidate log loss</th><th>FBS/FBS loss change</th></tr></thead><tbody>{''.join(summary)}</tbody></table></div>
<p>Lower log loss is better. The full-network excluded-game division coefficient changes from 2.40415 to 2.40131 after repair. The current candidate Top 25 retains its exact Round1 membership and order; only Mississippi State and James Madison exchange #35/#36 among all FBS teams. FBS/FBS benefits are small and are not uniformly better in every season.</p>
<p>There were 34 historical FCS upsets among these 602 crossdivision games. The candidate assigns those upsets lower probabilities and receives larger errors when they occur. Its overall score still improves because it better balances those rare outcomes against the 568 FBS wins. Future testing must watch individual-opponent calibration and overconfidence.</p>{calendar_note}
<h2>Current snapshot illustration</h2><p>This uses the saved November 5, 2026 evening snapshot. Both research methods receive the same games. Their nested control/candidate Top25 memberships agree, while their order differs. The candidate shares 24 Top25 teams with the older frozen SOR. None replaces the live Colley table below.</p><div class="scroll"><table><thead><tr><th>Candidate #</th><th>Team</th><th>Record</th><th>Live Colley</th><th>Old frozen SOR</th><th>Refitted control SOR</th><th>Division SOR</th></tr></thead><tbody>{rankings}</tbody></table></div>
<h2>Why teams move</h2><p>The detail tables show the chance an <strong>average FBS reference team</strong> would beat each opponent at that venue, with that game's result removed from the calculation. They are not forecasts of the listed team's own win probability. A more expected win supplies less SOR evidence. Each actual outcome is counted once; there is no second subdivision multiplier in the game network or record.</p>{''.join(details)}
<p>We also reversed each of the 122 FBS–FCS outcomes hypothetically, recalculating the affected opponent network. All 122 moved the team's SOR in the expected direction. The original observed results were preserved. A strong FCS opponent can still be harder than a weak FBS opponent; the term does not impose a universal ordering of individual teams.</p>
<h2>What runs next</h2><ol><li>Sunday's existing two-call CFBD refresh publishes the normal rankings.</li><li>The separate frozen candidate and matching refitted control produce immutable research SOR tables from the same inputs.</li><li>Available unfinished known-D1 games in the next seven days receive candidate/control forecasts, saved strictly before kickoff with checksummed capture times and inputs.</li><li>Later Sunday updates score the first eligible saved forecast against confirmed results. Postponements, identity changes and stale captures are excluded under the written rules.</li></ol>
<p>Candidate <code>{p['id']}</code> was frozen at <code>{p['frozenAt']}</code>. The first scheduled capture is November 8 at 8 AM Mountain; genuinely future results are pending. Tests use synthetic fixtures and cannot supply future evidence. New research steps can fail without blocking the public ranking update or the older frozen comparison.</p>
<h2>Limits that remain</h2><ul><li>The crossdivision evaluation sample has 595 FBS home games, seven neutral games and no FBS away games. This is not a causal neutral-field subdivision talent measure.</li><li>Some FCS regular-season and indirect lower-division context remains incomplete. Season2020 has missing roster identities and spring fixtures; no memberships were invented.</li><li>Sixty-seven unresolved provider field disagreements are FCS–FCS only: 36 neutral flags, 27 calendar labels, two kickoff times and two orientations. These do not change final-network Colley outcomes, but calendar choices can affect conservative preweek eligibility.</li><li>Better probabilities do not prove a uniquely correct achievement order. Current rank appearance was not a fitting target. No human polls or conference prestige bonuses were used.</li><li>Future crossdivision samples late in the season may be small. The model is not promoted automatically by agreement, a familiar Top25, or one week's forecast score.</li></ul>
<p><a href="current-ranks.csv">All 138 current ranks</a> · <a href="round2.json.gz">Full compressed numerical report</a> · <a href="metadata.json">Checksums</a> · <a href="../../../frozen-division-comparison-v2.json">Frozen parameters and evaluation rules</a></p><p>Run fingerprint <code>{r['runFingerprint']}</code>. Historical acquisition used 39 unauthenticated public requests and reused 18 cached responses. <strong>CFBD calls for Round2: zero.</strong> Normal weekly CFBD usage remains two successful calls.</p></html>'''
    (OUTPUT/'summary.html').write_bytes(doc.encode())
    print(OUTPUT/'summary.html')


if __name__=='__main__':main()
